//! `aporia agent` — the interactive research and engineering workbench.
//!
//! The command owns the words, the terminal rendering and the exit status; the engine owns the
//! loop. The person can talk to the investigation, watch what it does, approve or refuse work,
//! ask for more, and stop. Every decision is recorded before it takes effect, and the report at
//! the end is generated by the host from what was recorded.

use crate::run::Exit;
use aporia_agent::engine::{Controller, Engine, EngineConfig, EngineEvent, Outcome, Wait};
use aporia_agent::provider::http::HttpProvider;
use aporia_agent::provider::scripted::ScriptedProvider;
use aporia_agent::scope::{ApprovalRequest, Decision};
use aporia_agent::tools::{
    Registry, command, control, edit, files, instrument, intel, results, source_git,
};
use std::io::{BufRead, IsTerminal, Write};
use std::path::{Path, PathBuf};

const DEFAULT_MAX_TURNS: usize = 32;
const DEFAULT_MAX_TOOL_CALLS: usize = 64;
const DEFAULT_TOTAL_TIMEOUT_MS: u64 = 600_000;
const DEFAULT_WORKDIR: &str = ".aporia/investigations";

fn usage() -> &'static str {
    "usage: aporia agent <project-dir> --objective TEXT --provider PROVIDER\n\
     \x20   [--model NAME] [--workdir DIR] [--allow-exec PROGRAM]... [--allow-write]\n\
     \x20   [--max-turns N] [--max-tool-calls N] [--timeout MS] [--batch]\n\
     \x20 open an interactive investigation. The agent inspects the project, proposes a plan, and\n\
     \x20 waits for your approval before anything runs. PROVIDER is `scripted:<transcript.json>`\n\
     \x20 or `http://host:port/v1` (with --model).\n\
     \x20 aporia agent list [--workdir DIR]\n\
     \x20   list the investigations this work directory holds\n\
     \x20 aporia agent report <investigation-dir>\n\
     \x20   print a finished investigation's report without executing anything\n\
     \x20 help | --help                  this text\n\
     \x20 exit: 0 finished, 1 finished with a critical or high finding, 2 usage,\n\
     \x20     3 project or workspace unusable, 10 the plan was refused, 11 provider failure,\n\
     \x20     12 budget exhausted (the record is incomplete), 13 the record could not be written\n"
}

/// The controller that never decides: the person does, at the prompt.
struct Interactive;

impl Controller for Interactive {
    fn decide(&mut self, _request: &ApprovalRequest) -> Option<Decision> {
        None
    }

    fn event(&mut self, event: &EngineEvent) {
        render_event(event);
    }
}

/// The controller that approves everything inside the ceilings, for `--batch`.
struct ApproveAll;

impl Controller for ApproveAll {
    fn decide(&mut self, _request: &ApprovalRequest) -> Option<Decision> {
        Some(Decision::Approve)
    }

    fn event(&mut self, event: &EngineEvent) {
        render_event(event);
    }
}

struct Args {
    project: PathBuf,
    objective: String,
    provider: ProviderArg,
    model: Option<String>,
    workdir: PathBuf,
    allow_exec: Vec<String>,
    allow_write: bool,
    max_turns: usize,
    max_tool_calls: usize,
    timeout_ms: u64,
    batch: bool,
}

enum ProviderArg {
    Scripted(PathBuf),
    Http(String),
}

/// The command. `out` is for the conversation, `err` for refusals.
pub fn command(flags: &[String], out: &mut dyn Write, err: &mut dyn Write) -> Exit {
    if flags
        .iter()
        .any(|arg| arg == "--help" || arg == "-h" || arg == "help")
    {
        let _ = write!(out, "{}", usage());
        return Exit::Clean;
    }
    if flags.first().map(String::as_str) == Some("list") {
        return list_command(&flags[1..], out);
    }
    if flags.first().map(String::as_str) == Some("report") {
        return report_command(&flags[1..], out, err);
    }
    let args = match parse(flags) {
        Ok(args) => args,
        Err(reason) => {
            let _ = writeln!(err, "aporia agent: {reason}");
            let _ = write!(err, "{}", usage());
            return Exit::Usage;
        }
    };

    let provider: Box<dyn aporia_agent::ModelProvider> = match &args.provider {
        ProviderArg::Scripted(path) => match ScriptedProvider::load(path) {
            Ok(provider) => Box::new(provider),
            Err(error) => {
                let _ = writeln!(err, "aporia agent: {error}");
                return Exit::Provider;
            }
        },
        ProviderArg::Http(base) => {
            let Some(model) = &args.model else {
                let _ = writeln!(err, "aporia agent: an HTTP provider needs --model NAME");
                return Exit::Usage;
            };
            match HttpProvider::new(base, model, 120_000) {
                Ok(provider) => Box::new(provider),
                Err(error) => {
                    let _ = writeln!(err, "aporia agent: {error}");
                    return Exit::Provider;
                }
            }
        }
    };

    let instrument = match std::env::current_exe() {
        Ok(path) => path,
        Err(error) => {
            let _ = writeln!(err, "aporia agent: cannot find this executable: {error}");
            return Exit::Input;
        }
    };
    let config = EngineConfig {
        source: args.project.clone(),
        objective: args.objective.clone(),
        provider,
        allow_exec: args.allow_exec.clone(),
        allow_write: args.allow_write,
        max_turns: args.max_turns,
        max_tool_calls: args.max_tool_calls,
        total_timeout_ms: args.timeout_ms,
        workdir: args.workdir.clone(),
        instrument,
    };
    let controller: Box<dyn Controller> = if args.batch {
        Box::new(ApproveAll)
    } else {
        Box::new(Interactive)
    };
    let mut engine = match Engine::start(config, controller, registry()) {
        Ok(engine) => engine,
        Err(error) => {
            let _ = writeln!(err, "aporia agent: {error}");
            return Exit::Input;
        }
    };
    let _ = writeln!(
        out,
        "APORIA is investigating {}.\nType a message to add context, /help for the commands.",
        args.project.display()
    );
    run_session(&mut engine, out, err, args.batch)
}

/// The tools this application offers.
fn registry() -> Registry {
    let mut registry = Registry::new();
    control::register(&mut registry).expect("control tools");
    edit::register(&mut registry).expect("editing tools");
    files::register(&mut registry).expect("file tools");
    intel::register(&mut registry).expect("discovery tools");
    command::register(&mut registry).expect("command tool");
    instrument::register(&mut registry).expect("instrument tool");
    results::register(&mut registry).expect("result tools");
    source_git::register(&mut registry).expect("source git tool");
    registry
}

/// Drive the engine, answering approvals as they come.
fn run_session(engine: &mut Engine, out: &mut dyn Write, err: &mut dyn Write, batch: bool) -> Exit {
    if batch {
        return run_batch(engine, out, err);
    }
    loop {
        match engine.step() {
            Ok(aporia_agent::engine::Step::Turn) => {
                if let Some(exit) = conversation(engine, out, err) {
                    return exit;
                }
            }
            Ok(aporia_agent::engine::Step::Approval(request)) => {
                render_approval(out, &request);
                let decision = ask_approval(out, err).unwrap_or(Decision::Refuse);
                if let Err(error) = engine.decide(decision) {
                    let _ = writeln!(err, "aporia agent: {error}");
                    return Exit::Record;
                }
            }
            Ok(aporia_agent::engine::Step::Finished(outcome)) => {
                let _ = writeln!(out, "\ninvestigation {}", outcome.as_str());
                return exit_for(outcome, engine);
            }
            Err(error) => {
                let _ = writeln!(err, "aporia agent: {error}");
                return Exit::Record;
            }
        }
    }
}

/// The batch path: the controller approves what the ceilings allow, and the loop runs to the end.
fn run_batch(engine: &mut Engine, out: &mut dyn Write, err: &mut dyn Write) -> Exit {
    loop {
        match engine.resume() {
            Ok(Wait::Approval(request)) => {
                render_approval(out, &request);
                if let Err(error) = engine.decide(Decision::Approve) {
                    let _ = writeln!(err, "aporia agent: {error}");
                    return Exit::Record;
                }
            }
            Ok(Wait::Done(outcome)) => {
                let _ = writeln!(out, "\ninvestigation {}", outcome.as_str());
                return exit_for(outcome, engine);
            }
            Err(error) => {
                let _ = writeln!(err, "aporia agent: {error}");
                return Exit::Record;
            }
        }
    }
}

fn render_approval(out: &mut dyn Write, request: &ApprovalRequest) {
    let _ = writeln!(out, "\n--- approval needed: {}", request.title);
    if request.kind == aporia_agent::scope::ApprovalKind::Plan {
        let _ = writeln!(
            out,
            "The plan, its gaps and its tasks are in the investigation record."
        );
    }
}

fn ask_approval(out: &mut dyn Write, err: &mut dyn Write) -> Option<Decision> {
    let _ = write!(out, "approve? [y/N] ");
    let _ = out.flush();
    let mut line = String::new();
    match std::io::stdin().read_line(&mut line) {
        Ok(0) => None,
        Ok(_) => {
            let answer = line.trim().to_ascii_lowercase();
            if answer == "y" || answer == "yes" {
                Some(Decision::Approve)
            } else {
                Some(Decision::Refuse)
            }
        }
        Err(error) => {
            let _ = writeln!(err, "aporia agent: cannot read the answer: {error}");
            None
        }
    }
}

fn render_event(event: &EngineEvent) {
    match event {
        EngineEvent::Tool {
            name, ok, detail, ..
        } => {
            let mark = if *ok { "ok" } else { "failed" };
            let first = detail.lines().next().unwrap_or("");
            println!("  [{mark}] {name}: {first}");
        }
        EngineEvent::PlanProposed { version } => {
            println!("  plan version {version} was proposed");
        }
        EngineEvent::Experiment { id, status } => {
            println!("  experiment {id} is {status}");
        }
        EngineEvent::Finished { outcome } => {
            println!("investigation {outcome}");
        }
        _ => {}
    }
}

/// The conversation: the person may speak, or use a command.
fn conversation(engine: &mut Engine, out: &mut dyn Write, err: &mut dyn Write) -> Option<Exit> {
    let stdin = std::io::stdin();
    let mut line = String::new();
    loop {
        let _ = write!(out, "\n> ");
        let _ = out.flush();
        line.clear();
        match stdin.lock().read_line(&mut line) {
            Ok(0) => return Some(Exit::Clean),
            Ok(_) => {}
            Err(error) => {
                let _ = writeln!(err, "aporia agent: cannot read: {error}");
                return Some(Exit::Input);
            }
        }
        let text = line.trim();
        if text.is_empty() {
            continue;
        }
        if let Some(command) = text.strip_prefix('/') {
            match command {
                "help" => {
                    let _ = write!(out, "{}", commands_help());
                }
                "quit" | "exit" => return Some(Exit::Clean),
                "cancel" => {
                    engine.cancel();
                    let _ = writeln!(out, "the investigation will stop at the next opportunity");
                }
                "status" => {
                    let _ = writeln!(
                        out,
                        "status {}, phase {}, tools: {}",
                        engine.status().as_str(),
                        engine.phase().as_str(),
                        engine.tool_names().join(", ")
                    );
                }
                "plan" => {
                    let investigation = engine.investigation();
                    if let Some(revision) = investigation.approved_revision() {
                        let _ = writeln!(
                            out,
                            "approved plan version {} with {} gaps and {} tasks",
                            revision.version,
                            revision.proposal.gaps.len(),
                            revision.proposal.tasks.len()
                        );
                    } else {
                        let _ = writeln!(out, "no plan has been approved yet");
                    }
                }
                "gaps" => {
                    let investigation = engine.investigation();
                    for revision in &investigation.revisions {
                        for gap in &revision.proposal.gaps {
                            let _ = writeln!(
                                out,
                                "{} [{}] {} (evidence: {})",
                                gap.id,
                                gap.priority.as_str(),
                                gap.title,
                                gap.evidence.join(", ")
                            );
                        }
                    }
                }
                "tools" => {
                    for name in engine.tool_names() {
                        let _ = writeln!(out, "{name}");
                    }
                }
                "experiments" => {
                    let investigation = engine.investigation();
                    for experiment in investigation.ranked_experiments() {
                        let _ = writeln!(
                            out,
                            "{} [{}] {} — {}",
                            experiment.id,
                            experiment.status.as_str(),
                            experiment.priority,
                            experiment.title
                        );
                    }
                }
                "changes" => {
                    let _ = writeln!(out, "no changes have been made to the workspace yet");
                }
                "approve" | "deny" | "save" => {
                    let _ = writeln!(out, "`{command}` has nothing to do at this moment");
                }
                other => {
                    let _ = writeln!(err, "aporia agent: unknown command `/{other}`; try /help");
                }
            }
            continue;
        }
        engine.say(text.to_string());
        return None;
    }
}

fn commands_help() -> &'static str {
    "/help        this text\n\
     /status      what the investigation is doing now\n\
     /plan        the approved plan, if there is one\n\
     /gaps        the gaps the investigation has found\n\
     /tools       the tools available in this session\n\
     /experiments the improvement backlog\n\
     /changes     the changes made in the workspace\n\
     /cancel      stop at the next opportunity\n\
     /quit        leave; the record stays on disk\n\
     \n\
     Anything else is a message to the agent, added to the conversation.\n"
}

fn exit_for(outcome: Outcome, engine: &Engine) -> Exit {
    match outcome {
        Outcome::Completed => {
            let severe = engine.investigation().findings.iter().any(|finding| {
                matches!(
                    finding.severity,
                    aporia_agent::Severity::Critical | aporia_agent::Severity::High
                )
            });
            if severe {
                Exit::Suspicious
            } else {
                Exit::Clean
            }
        }
        Outcome::NoPlan | Outcome::Cancelled => Exit::Clean,
        Outcome::Refused => Exit::Refused,
        Outcome::Failed => Exit::Provider,
        Outcome::BudgetExhausted => Exit::Budget,
    }
}

fn list_command(flags: &[String], out: &mut dyn Write) -> Exit {
    let mut workdir = PathBuf::from(DEFAULT_WORKDIR);
    let mut index = 0;
    while index < flags.len() {
        if flags[index] == "--workdir" {
            index += 1;
            if let Some(path) = flags.get(index) {
                workdir = PathBuf::from(path);
            } else {
                let _ = writeln!(out, "aporia agent list: --workdir needs a directory");
                return Exit::Usage;
            }
        }
        index += 1;
    }
    let entries = match std::fs::read_dir(&workdir) {
        Ok(entries) => entries,
        Err(error) => {
            let _ = writeln!(
                out,
                "aporia agent list: cannot read {}: {error}",
                workdir.display()
            );
            return Exit::Input;
        }
    };
    let mut directories: Vec<PathBuf> = entries
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.is_dir())
        .collect();
    directories.sort();
    if directories.is_empty() {
        let _ = writeln!(out, "no investigations in {}", workdir.display());
        return Exit::Clean;
    }
    for directory in directories {
        match aporia_agent::read_checkpoint(&directory) {
            Ok(Some(state)) => {
                let _ = writeln!(
                    out,
                    "{}  {}  {}  {}",
                    directory.file_name().unwrap_or_default().to_string_lossy(),
                    state.status.as_str(),
                    state.phase.as_str(),
                    state.objective
                );
            }
            Ok(None) => {
                let _ = writeln!(
                    out,
                    "{}  (no checkpoint)",
                    directory.file_name().unwrap_or_default().to_string_lossy()
                );
            }
            Err(error) => {
                let _ = writeln!(out, "{}  unreadable: {error}", directory.display());
            }
        }
    }
    Exit::Clean
}

fn report_command(flags: &[String], out: &mut dyn Write, err: &mut dyn Write) -> Exit {
    let positional: Vec<&String> = flags.iter().filter(|arg| !arg.starts_with("--")).collect();
    if positional.len() != 1 {
        let _ = writeln!(err, "aporia agent report: expected exactly one directory");
        return Exit::Usage;
    }
    let root = Path::new(positional[0]);
    match aporia_agent::verify_record(root) {
        Ok(summary) => {
            let _ = writeln!(out, "investigation {positional:?}");
            let _ = writeln!(out, "outcome {}", summary.outcome);
            let _ = writeln!(
                out,
                "journal {} events, head {}",
                summary.events, summary.head
            );
            match std::fs::read_to_string(root.join("report.md")) {
                Ok(text) => {
                    let _ = writeln!(out, "\n{text}");
                    Exit::Clean
                }
                Err(error) => {
                    let _ = writeln!(err, "aporia agent report: cannot read the report: {error}");
                    Exit::Integrity
                }
            }
        }
        Err(error) => {
            let _ = writeln!(err, "aporia agent report: {error}");
            Exit::Integrity
        }
    }
}

fn parse(flags: &[String]) -> Result<Args, String> {
    let mut project = None;
    let mut objective = None;
    let mut provider = None;
    let mut model = None;
    let mut workdir = PathBuf::from(DEFAULT_WORKDIR);
    let mut allow_exec = Vec::new();
    let mut allow_write = false;
    let mut max_turns = DEFAULT_MAX_TURNS;
    let mut max_tool_calls = DEFAULT_MAX_TOOL_CALLS;
    let mut timeout_ms = DEFAULT_TOTAL_TIMEOUT_MS;
    let mut batch = false;
    let mut index = 0;
    while index < flags.len() {
        let flag = flags[index].as_str();
        let value = |index: &mut usize, name: &str| -> Result<String, String> {
            *index += 1;
            flags
                .get(*index)
                .cloned()
                .ok_or_else(|| format!("{name} needs a value"))
        };
        match flag {
            "--objective" => objective = Some(value(&mut index, "--objective")?),
            "--provider" => {
                let text = value(&mut index, "--provider")?;
                if let Some(path) = text.strip_prefix("scripted:") {
                    if path.is_empty() {
                        return Err("--provider scripted: needs a transcript path".to_string());
                    }
                    provider = Some(ProviderArg::Scripted(PathBuf::from(path)));
                } else if text.starts_with("http://") || text.starts_with("https://") {
                    provider = Some(ProviderArg::Http(text));
                } else {
                    return Err(
                        "--provider must be `scripted:<path>` or `http://host:port/v1`".to_string(),
                    );
                }
            }
            "--model" => model = Some(value(&mut index, "--model")?),
            "--workdir" => workdir = PathBuf::from(value(&mut index, "--workdir")?),
            "--allow-exec" => allow_exec.push(value(&mut index, "--allow-exec")?),
            "--allow-write" => allow_write = true,
            "--batch" => batch = true,
            "--max-turns" => max_turns = number(&value(&mut index, "--max-turns")?, "--max-turns")?,
            "--max-tool-calls" => {
                max_tool_calls =
                    number(&value(&mut index, "--max-tool-calls")?, "--max-tool-calls")?;
            }
            "--timeout" => timeout_ms = number(&value(&mut index, "--timeout")?, "--timeout")?,
            other if other.starts_with("--") => {
                return Err(format!("unknown flag `{other}`"));
            }
            other => {
                if project.is_some() {
                    return Err(format!("unexpected second project path `{other}`"));
                }
                project = Some(PathBuf::from(other));
            }
        }
        index += 1;
    }
    let project = project.ok_or_else(|| "a project directory is required".to_string())?;
    let objective = objective.ok_or_else(|| "--objective is required".to_string())?;
    if objective.trim().is_empty() || objective.len() > 4096 {
        return Err("--objective must be 1 to 4096 characters".to_string());
    }
    let provider = provider.ok_or_else(|| "--provider is required".to_string())?;
    if matches!(provider, ProviderArg::Scripted(_)) && model.is_some() {
        return Err("--model is only used by an HTTP provider".to_string());
    }
    for program in &allow_exec {
        if program.is_empty()
            || program.contains('/')
            || program.contains('\\')
            || program.contains(' ')
        {
            return Err("--allow-exec takes a bare program name".to_string());
        }
    }
    Ok(Args {
        project,
        objective,
        provider,
        model,
        workdir,
        allow_exec,
        allow_write,
        max_turns,
        max_tool_calls,
        timeout_ms,
        batch,
    })
}

fn number<T>(text: &str, flag: &str) -> Result<T, String>
where
    T: std::str::FromStr,
{
    text.parse().map_err(|_| format!("{flag} needs a number"))
}

/// Whether standard input is a terminal: the workbench is interactive when it is.
#[must_use]
pub fn interactive() -> bool {
    std::io::stdin().is_terminal()
}
